def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each one-cell hole in a horizontal bar is an anchor for a vertical track.
    anchors = {}
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                anchors.setdefault(c, []).append((r, color))

    for c, marks in anchors.items():
        marks.sort()

        # Above the first anchor, continue its color upward.
        first_r, first_color = marks[0]
        for r in range(first_r, -1, -1):
            if out[r][c] == 0:
                out[r][c] = first_color

        # Between anchors, continue the lower anchor's color upward.
        for (prev_r, _), (r, color) in zip(marks, marks[1:]):
            for rr in range(prev_r + 1, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color

        # Below the final anchor, extend the vertical stem found in that column.
        last_r = marks[-1][0]
        stem_color = next(
            (grid[r][c] for r in range(last_r + 1, h) if grid[r][c] != 0),
            None
        )
        if stem_color is not None:
            for r in range(last_r + 1, h):
                if out[r][c] == 0:
                    out[r][c] = stem_color

    return out
